// Build-time generator: writes a C++ source that embeds the FLUTE lookup tables
// as string literals so the library never opens files at runtime.
//   flute_embed_gen POWV9.dat POST9.dat flute_lut_data.cpp
#include <cstdio>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>

namespace {

bool emit(const char *name, const char *path) {
  std::ifstream input(path, std::ios::binary);
  if (!input) {
    std::cerr << "flute_embed_gen: cannot open " << path << '\n';
    return false;
  }
  const std::string data((std::istreambuf_iterator<char>(input)),
                         std::istreambuf_iterator<char>());
  std::printf("alignas(16) const char %s[] =\n\"", name);
  size_t column = 0;
  for (const unsigned char c : data) {
    // Fixed-width octal escapes cannot merge with a following digit and avoid
    // trigraph/quote/backslash pitfalls; printable bytes stay readable.
    if (c >= 0x20 && c < 0x7f && c != '"' && c != '\\' && c != '?') {
      std::putchar(c);
      column += 1;
    } else {
      std::printf("\\%03o", c);
      column += 4;
    }
    if (column >= 96) {
      std::printf("\"\n\"");
      column = 0;
    }
  }
  std::printf("\";\nconst std::size_t %s_size = %zu;\n\n", name, data.size());
  return true;
}

} // namespace

int main(int argc, char **argv) {
  if (argc != 4) {
    std::cerr << "usage: flute_embed_gen POWV9.dat POST9.dat OUT.cpp\n";
    return 2;
  }
  if (std::freopen(argv[3], "w", stdout) == nullptr) {
    std::cerr << "flute_embed_gen: cannot write " << argv[3] << '\n';
    return 1;
  }
  std::printf(
      "// Generated by flute_embed_gen from lut.ICCAD2015. Do not edit.\n"
      "#include <cstddef>\n\n"
      "namespace flute::lut_embedded {\n"
      "extern const char powv9[];\n"
      "extern const std::size_t powv9_size;\n"
      "extern const char post9[];\n"
      "extern const std::size_t post9_size;\n\n");
  if (!emit("powv9", argv[1]) || !emit("post9", argv[2]))
    return 1;
  std::printf("}  // namespace flute::lut_embedded\n");
  return std::fclose(stdout) == 0 ? 0 : 1;
}
